func UpdatedAtLTE(v time.Time) predicate.BundlePromotions {
	return predicate.BundlePromotions(sql.FieldLTE(FieldUpdatedAt, v))
}

// HasBundle applies the HasEdge predicate on the "bundle" edge.
func HasBundle() predicate.BundlePromotions {
	return predicate.BundlePromotions(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, BundleTable, BundleColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasBundleWith applies the HasEdge predicate on the "bundle" edge with a given conditions (other predicates).
func HasBundleWith(preds ...predicate.Bundles) predicate.BundlePromotions {
	return predicate.BundlePromotions(func(s *sql.Selector) {
		step := newBundleStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.BundlePromotions) predicate.BundlePromotions {
	return predicate.BundlePromotions(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.BundlePromotions) predicate.BundlePromotions {
	return predicate.BundlePromotions(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.BundlePromotions) predicate.BundlePromotions {
	return predicate.BundlePromotions(sql.NotPredicates(p))
}
